# Level 0 (RPC over HTTP) — everything is a POST, always 200
POST /api
{"action": "cancelOrder", "id": 99}
--> 200 OK  {"ok": false, "error": "not found"}

# Level 2 (resources + honest verbs + status codes)
GET    /orders/99            --> 200 OK        (safe, cacheable)
GET    /orders/12345         --> 404 Not Found
PATCH  /orders/99            --> 200 OK        (idempotent cancel)
       {"status": "cancelled"}
POST   /orders               --> 201 Created + Location: /orders/100
       {"item": "book", "qty": 1}
DELETE /orders/99            --> 204 No Content (idempotent)
